class InvoiceRepository(db: Database) {
  private val invoices = TableQuery[Invoices]

  def findOverdue(on: LocalDate): Future[Seq[Invoice]] =
    db.run(invoices.filter(_.due < on).result)        // collection-like, executed async

  def add(invoice: Invoice): Future[Int] =
    db.run(invoices += invoice)                       // compose DBIO for atomic units
}
